package studio.jiayu.neoagent;
import android.graphics.Rect;import android.view.accessibility.AccessibilityNodeInfo;import org.json.*;import java.util.*;
/** Explicit bounded purchase tools. A normal tap can never acquire a financial exception. */
final class PurchaseRuntime {
 final ControlService owner;final boolean synthetic;final PurchaseLedger ledger;private Armed armed;
 static final class Armed {long epoch;ControlService.Observation source;String identity,fingerprint;Rect bounds;int id;boolean issued;}
 PurchaseRuntime(ControlService s){this(s,false);}
 PurchaseRuntime(ControlService s,boolean test){owner=s;synthetic=test;ledger=new PurchaseLedger(s,test);}
 PurchasePolicy.Grant grant(){String original=owner.activeRequest==null?"":owner.activeRequest.original;String pkg=synthetic&&owner.allowed.equals(owner.getPackageName())?"com.taobao.taobao":owner.allowed;if(owner.activeRequest!=null&&owner.activeRequest.sharedComparison)return PurchasePolicy.grant("",pkg);return PurchasePolicy.grant(original,pkg);}
 boolean authorized(){return grant().order;}
 void collect(AccessibilityNodeInfo n,List<String> labels,boolean[] unsafe,int depth,int[] count){if(n==null||depth>30||++count[0]>350||!n.isVisibleToUser()||n.isPassword())return;CharSequence text=n.getText(),description=n.getContentDescription();if(text!=null&&text.length()<=500)labels.add(text.toString());if(description!=null&&description.length()<=500&&!description.equals(text))labels.add(description.toString());String label=NativeLabels.label(n);if((n.isChecked()||n.isSelected())&&label.matches("(?s).*(白条|花呗|分期|先用后付|保险|延保|会员|连续包月|开通授信).*"))unsafe[0]=true;for(int i=0;i<n.getChildCount();i++)collect(n.getChild(i),labels,unsafe,depth+1,count);}
 PurchaseFacts facts(){if(android.os.Build.VERSION.SDK_INT>=33&&owner.connected)owner.clearCache();AccessibilityNodeInfo root=owner.getRootInActiveWindow();if(root==null||!owner.allowed.contentEquals(root.getPackageName()))return new PurchaseFacts();ArrayList<String> labels=new ArrayList<>();boolean[] unsafe={false};collect(root,labels,unsafe,0,new int[]{0});return PurchaseFacts.read(labels,unsafe[0]);}
 PurchaseState refreshed()throws Exception{PurchaseState s=ledger.load();if(s.reconcile(owner.allowed,facts(),System.currentTimeMillis()))ledger.save(s);return s;}
 JSONObject status()throws Exception{PurchasePolicy.Grant g=grant();JSONObject result=new JSONObject().put("authorized",g.order).put("synthetic",synthetic);if(!g.order)return result;PurchaseState s=refreshed();PurchaseFacts f=facts();return result.put("cap_cents",g.cap).put("quantity_limit",1).put("currency","CNY").put("payment_allowed",g.pay).put("state",s.state).put("same_goal",s.run.equals(owner.runId)).put("native_total_cents",f.total).put("native_quantity",f.quantity).put("shipping_included",f.shippingIncluded).put("delivery_selected",f.deliverySelected).put("native_order_facts_valid",PurchasePolicy.validOrder(g,f)).put("order_created_verified",s.run.equals(owner.runId)&&(s.state.equals(PurchaseState.ORDER_VERIFIED)||s.state.equals(PurchaseState.PAY_PENDING)||s.state.equals(PurchaseState.PAID))).put("paid_verified",s.paidFor(owner.runId)).put("must_not_repeat",s.pending()||s.run.equals(owner.runId)&&!s.state.equals(PurchaseState.EMPTY));}
 boolean verifiedHere()throws Exception{PurchaseState s=refreshed();return !synthetic&&s.merchant.equals(owner.allowed)&&s.run.equals(owner.runId)&&(s.state.equals(PurchaseState.PAID)||!grant().pay&&s.state.equals(PurchaseState.ORDER_VERIFIED));}
 boolean paid()throws Exception{return authorized()&&refreshed().paidFor(owner.runId);}
 boolean complete()throws Exception{if(!authorized())return false;PurchaseState s=refreshed();return s.paidFor(owner.runId)||!grant().pay&&s.run.equals(owner.runId)&&s.state.equals(PurchaseState.ORDER_VERIFIED);}
 boolean pendingForRun(){try{PurchaseState s=ledger.load();return authorized()&&s.run.equals(owner.runId)&&s.pending();}catch(Exception unreadable){return false;}}
 String completion()throws Exception{PurchaseState s=ledger.load();return s.paidFor(owner.runId)?(synthetic?"合成演示 · ":s.merchant.equals("com.taobao.taobao")?"淘宝 · ":"京东 · ")+"原生回执已核验付款成功 · 一件 · 含运费实付¥"+java.math.BigDecimal.valueOf(s.amount,2).toPlainString():"原生回执已核验订单已创建 · 按本次要求未付款";}
 String instructions(){if(!authorized())return "";return " 本机small_purchase.authorized=true：原用户明确授权本轮购买一件、含运费实付不超过本机cap_cents的普通实物。优先从价格明确不超过预算的搜索结果挑选；超过预算的详情先返回换商品，不把新人价、满减或待领取券当最终价。尽量选择立即购买入口，不操作已有购物车。选百洁布、抽纸等普通日用品，拒绝定金、虚拟品、充值、会员、保险、分期及先用后付；使用已有默认收货地址，不新增地址。普通tap仍禁止提交付款；仅可输出{\"action\":\"purchase_submit\",\"id\":原生提交按钮编号}或{\"action\":\"purchase_pay\",\"id\":原生付款按钮编号}，本机再次核验原生金额、数量与订单身份后决定是否执行。purchase_submit只支持确认订单页上的提交订单、提交并支付、确认并支付或确认下单；必须先看到native_order_facts_valid=true且订单核对标题、配送及运费齐全。purchase_pay只支持已核验本轮订单号的收银台，不支持从商品规格页直接付款。规格页的立即支付即使低于预算也不满足提交工具条件，不能用tap、坐标或换另一个财务工具反复尝试。若rejected_actions显示按钮不受支持，先返回商品详情寻找标准订单核对入口；没有则换其他商品继续探索，仍不可用时清楚说明停点，不要求用户重复授权已授权范围。检查工具{\"action\":\"purchase_check\"}。结果不明只查看订单回执，不能重新提交；待付款不等于付款成功。密码、验证码、面容或银行确认由用户处理。遇到未支持的原生金额布局，重新观察和寻找完整订单金额，不用模型估算，不尝试普通坐标绕过。";}
 String execute(Action action,long g,ControlService.Observation source)throws Exception{
  PurchasePolicy.Grant grant=grant();if(!grant.order)throw new ControlService.LocalBoundaryException("本目标没有小额正式购买授权，未提交");
  final String[] previous={null};final Armed[] permit={null};
  int[] point=owner.ui(()->{
   owner.validateObservation(source,g);owner.guard(g);PurchaseFacts f=facts();PurchaseState state=refreshed();int id=action.data.getInt("id");AccessibilityNodeInfo node=source.targets.get(id);
   if(node==null||!node.refresh()||!node.isClickable()||!node.isEnabled()||!GuiRevision.identity(node).equals(source.identities.get(id)))throw new ControlService.UiChangedException();
   String label=NativeLabels.label(node).replaceAll("\\s+","");boolean submit=action.name.equals("purchase_submit");
   if(submit?!label.matches("^(提交订单|提交并支付|确认并支付|确认下单)(?:¥[0-9.]+)?$"):!label.matches("^(立即支付|确认支付|确认付款|立即付款|支付订单)(?:¥[0-9.]+)?$"))throw new ControlService.LocalBoundaryException("按钮不是支持的原生提交或付款控件，未执行");
   previous[0]=ledger.raw();try{if(submit)state.armSubmit(owner.runId,owner.allowed,grant,f,System.currentTimeMillis());else state.armPay(owner.runId,owner.allowed,grant,f,System.currentTimeMillis());}catch(IllegalStateException denied){throw new ControlService.LocalBoundaryException(denied.getMessage());}
   Rect bounds=new Rect();node.getBoundsInScreen(bounds);if(bounds.isEmpty()||!source.appBounds.contains(bounds))throw new ControlService.LocalBoundaryException("提交按钮边界未核验");int inset=Math.min(owner.dp(2),Math.max(0,(Math.min(bounds.width(),bounds.height())-3)/2));Rect inner=new Rect(bounds);inner.inset(inset,inset);int[] touch=owner.touchPoints.pick(inner.left,inner.top,inner.right,inner.bottom,bounds.centerX(),bounds.centerY(),Math.max(1,owner.dp(4)));
   Armed a=new Armed();a.epoch=g;a.source=source;a.id=id;a.identity=GuiRevision.identity(node);a.fingerprint=f.fingerprint();a.bounds=bounds;ledger.save(state);armed=a;permit[0]=a;return touch;
  });
  try{owner.gesturePixels(point[0],point[1],point[0],point[1],70,g,action.data.getInt("id"));return action.name.equals("purchase_submit")?"提交请求已发出，等待原生订单回执；不会重复提交":"付款请求已发出，等待原生付款回执；不会重复付款";}
  finally{Armed a=permit[0];armed=null;if(a!=null&&!a.issued&&previous[0]!=null)ledger.raw(previous[0]);}
 }
 void ensure(Armed a)throws Exception{if(a==null||!owner.running||owner.generation!=a.epoch||!owner.ownership.current(a.source.id)||owner.currentObservation!=a.source)throw new ControlService.UiChangedException();owner.validateObservation(a.source,a.epoch);if(!facts().fingerprint().equals(a.fingerprint))throw new ControlService.UiChangedException();}
 boolean allowsNode(AccessibilityNodeInfo n)throws Exception{Armed a=armed;if(a==null)return false;if(!GuiRevision.identity(n).equals(a.identity))return false;ensure(a);return true;}
 boolean allowsArea(ControlService.Observation source,Rect area,Rect path)throws Exception{Armed a=armed;if(a==null||source!=a.source||!area.equals(a.bounds)||!a.bounds.contains(path))return false;ensure(a);return true;}
 void beforeGesture(long g,int id)throws Exception{Armed a=armed;if(a==null)return;if(a.epoch!=g||a.id!=id)throw new ControlService.UiChangedException();ensure(a);a.issued=true;}
}
